let mongo,client,database,auth,adminApp,app,store,http,frontendHttp,browser;const accounts={},students=[],offers=[],passwords=new Map();
async function token(email){const response=await fetch('http://127.0.0.1:9298/identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key=fake-api-key',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password:passwords.get(email)||'DemoPassword123!',returnSecureToken:true})});const result=await response.json();assert.ok(result.idToken,JSON.stringify(result));return result.idToken;}
const api=async(role,path,body)=>request(app).post(path).set('Authorization',`Bearer ${await token(accounts[role].email)}`).send(body);
async function departmentOffice(id){const d=await database.collection('departments').findOne({_id:id});assert.ok(d);let office=await database.collection('users').findOne({role:'office',scope:'department',departmentId:id,accountStatus:{$ne:'inactive'}});if(!office){const row={name:d.code+' Department Office',collegeEmail:'audit-office-'+d.code.toLowerCase()+'@demo.test',role:'office',scope:'department',departmentId:id,department:d.code,facultyId:'AUDIT-OFFICE-'+d.code};const result=await api('super_admin','/api/admin',{action:'provision',row,requestId:'audit-dept-office-'+id});assert.equal(result.status,200,JSON.stringify(result.body));office=await database.collection('users').findOne({_id:result.body.uid});}accounts['office-'+d.code]={uid:office._id,email:office.email};return office._id;}
async function assertTemporaryStillRequired(email,bearer){const profile=await database.collection('users').findOne({email}),lookup=await(await fetch('http://127.0.0.1:9298/identitytoolkit.googleapis.com/v1/accounts:lookup?key=fake-api-key',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idToken:bearer})})).json(),response=await request(app).post('/api/auth/password-complete').set('Authorization','Bearer '+bearer).send({});assert.equal(response.status,403,JSON.stringify({mustChangePassword:profile.mustChangePassword,issuedAt:profile.temporaryPasswordIssuedAt,firebasePasswordUpdatedAt:Number(lookup.users?.[0]?.passwordUpdatedAt),differenceMs:Number(lookup.users?.[0]?.passwordUpdatedAt)-new Date(profile.temporaryPasswordIssuedAt).getTime()}));}
async function admin(data){const response=await api('admin','/api/admin',data);assert.equal(response.status,200,JSON.stringify(response.body));return response.body;}
async function finishTemporary(email){const before=await token(email),changed=await fetch('http://127.0.0.1:9298/identitytoolkit.googleapis.com/v1/accounts:update?key=fake-api-key',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idToken:before,password:'ChangedAudit123!',returnSecureToken:true})}),result=await changed.json();assert.ok(result.idToken,JSON.stringify(result));passwords.set(email,'ChangedAudit123!');const done=await request(app).post('/api/auth/password-complete').set('Authorization','Bearer '+await token(email)).send({});assert.equal(done.status,200,JSON.stringify(done.body));}
