test('request has exact teacher approvals, Library/Accounts and no lab approvals',async()=>{const response=await api('student1','/api/requests',{});assert.equal(response.status,200,JSON.stringify(response.body));requestId=response.body.id;const r=(await store.doc('noDueRequests/'+requestId).get()).data();assert.equal(Object.keys(r.approvalItems).length,5);assert.equal(r.approvalItems.physics_lab,undefined);assert.equal(r.approvalItems.chemistry_lab,undefined);assert.ok(Object.values(r.approvalItems).filter(i=>i.teacherUid).every(i=>i.teacherUid===accounts.teacher2.uid));});
test('wrong teacher cannot approve; rejection notifies only owner and resubmits with reason history',async()=>{const key='subject_'+offers[1].id;assert.equal((await api('subject_faculty',`/api/requests/${requestId}/actions`,{action:'stage1',approvalId:key,decision:'approved'})).status,403);assert.equal((await api('teacher2',`/api/requests/${requestId}/actions`,{action:'stage1',approvalId:key,decision:'rejected',reason:''})).status,400);assert.equal((await api('teacher2',`/api/requests/${requestId}/actions`,{action:'stage1',approvalId:key,decision:'rejected',reason:'Assignment pending'})).status,200);const notice=await database.collection('notifications').findOne({requestId});assert.equal(notice.studentId,students[1].uid);assert.equal(notice.reason,'Assignment pending');assert.equal(await database.collection('notifications').countDocuments({studentId:students[0].uid,requestId}),0);assert.equal((await api('student1',`/api/requests/${requestId}/actions`,{action:'resubmit'})).status,200);});
test('parallel Stage 1 transactions lead to Mentor, HOD, Office and issuance history',async()=>{const r=(await store.doc('noDueRequests/'+requestId).get()).data();const responses=await Promise.all(Object.entries(r.approvalItems).map(([key,item])=>api(item.approverType==='subject_faculty'?'teacher2':key,`/api/requests/${requestId}/actions`,{action:'stage1',approvalId:key,decision:'approved'})));assert.ok(responses.every(r=>r.status===200),JSON.stringify(responses.map(r=>r.body)));assert.equal((await store.doc('noDueRequests/'+requestId).get()).data().status,'pending_mentor');for(const action of ['mentor','hod'])assert.equal((await api(action,`/api/requests/${requestId}/actions`,{action,decision:'approved'})).status,200);assert.equal((await api('office',`/api/requests/${requestId}/actions`,{action:'issue'})).status,200);assert.equal((await store.doc('noDueRequests/'+requestId).get()).data().status,'issued');assert.ok(await database.collection('hallTickets').findOne({_id:requestId}));assert.equal((await api('office',`/api/requests/${requestId}/actions`,{action:'issue'})).status,200);});
