const marksCall=async(role,id,action,body)=>{const call=request(app)[body===undefined?'get':'post'](`/api/marks-csv/${id}/${action}`).set('Authorization','Bearer '+await token(accounts[role].email));return body===undefined?call:call.send(body);};
const csvOf=(rows,headers=Object.keys(rows[0]))=>headers.join(',')+'\n'+rows.map(r=>headers.map(k=>'"'+String(r[k]??'').replaceAll('"','""')+'"').join(',')).join('\n');
