test('Chrome rejection editors survive typing and polling for faculty, Library, Accounts, Mentor and HOD',async()=>{
 const created=await api('student0','/api/requests',{requestKey:'stable-editor-all-roles'});assert.equal(created.status,200);const id=created.body.id,reason='Assignment pending. Please submit before clearance.';
 const student=await browserLogin('student0');
 for(const role of ['subject_faculty','library','accounts','sports','mentor','hod']){
   const actor=await browserLogin(role),stage=['mentor','hod'].includes(role),key=role==='subject_faculty'?'subject_'+offers[0].id:role;
   await actor.page.goto(`http://127.0.0.1:5051/${stage?role:'approver'}-dashboard.html#requests`);
   const row=actor.page.locator(stage?`[data-request-id="${id}"]`:`[data-path="noDueRequests/${id}/approvals/${key}"]`);
   await row.waitFor();let failedPolls=0;await actor.context.route('**/api/data/query',async route=>{if(route.request().postDataJSON().path==='noDueRequests'&&failedPolls===0){failedPolls++;return route.fulfill({status:503,contentType:'application/json',body:JSON.stringify({error:{message:'Audit transient polling failure'}})});}return route.continue();});
   await row.locator('.reject-btn').click();const input=row.locator('textarea'),handle=await input.elementHandle();
   for(const letter of reason){await input.pressSequentially(letter,{delay:85});assert.ok(await handle.evaluate(e=>e.isConnected&&document.activeElement===e));}
   await actor.page.waitForTimeout(3300);assert.equal(await input.inputValue(),reason);assert.ok(await handle.evaluate(e=>e.isConnected));assert.equal(failedPolls,1);
   assert.equal((await database.collection('noDueRequests').findOne({_id:id})).status,stage?(role==='mentor'?'pending_mentor':'pending_hod'):'pending_stage1');
   await row.locator('.cancel-rejection').click();assert.equal(await actor.page.locator('textarea:visible').count(),0);
   const fresh=actor.page.locator(stage?`[data-request-id="${id}"]`:`[data-path="noDueRequests/${id}/approvals/${key}"]`);await fresh.locator('.reject-btn').click();await fresh.locator('textarea').fill(reason);await fresh.getByRole('button',{name:'Confirm Reject',exact:true}).click();
   for(let n=0;n<40;n++){if((await database.collection('noDueRequests').findOne({_id:id})).status==='rejected')break;await actor.page.waitForTimeout(100);}
   const saved=await database.collection('noDueRequests').findOne({_id:id});assert.equal(saved.status,'rejected');assert.equal(saved.lastEvent.reason,reason);
   await student.page.goto('http://127.0.0.1:5051/student-dashboard.html#requests');await student.page.reload();await student.page.getByText(reason,{exact:false}).first().waitFor();
   assert.equal((await api('student0',`/api/requests/${id}/actions`,{action:'resubmit'})).status,200);
   await actor.page.locator(stage?`[data-request-id="${id}"] .reject-btn`:`[data-path="noDueRequests/${id}/approvals/${key}"] .reject-btn`).waitFor();
   assert.equal((await api(role,`/api/requests/${id}/actions`,stage?{action:role,decision:'approved'}:{action:'stage1',approvalId:key,decision:'approved'})).status,200);
   await actor.context.close();
 }
 await student.context.close();
});
