let retryTemplate, retrySubjects;
const retryPath=id=>`/api/requests/${id}/actions`;
async function retryAction(role,id,body){const response=await api(role,retryPath(id),body);if(response.status!==200){const current=await database.collection('noDueRequests').findOne({_id:id});assert.fail(JSON.stringify({role,action:body.action,response:response.body,status:current?.status,mentor:current?.mentorApproval,hod:current?.hodApproval}));}return response;}
async function retryRecords(id){return database.collection('approvals').find({requestId:id}).sort({_id:1}).toArray();}

