 const created=await api('retryStudent','/api/requests',{requestKey:'same-teacher-two-subject-retry'});assert.equal(created.status,200);const id=created.body.id;
 retryTemplate=structuredClone((await store.doc('noDueRequests/'+id).get()).data());
 // Complete the unrelated subject/services; the exact two Aarav subject rows remain.
 for(const [key,item]of Object.entries(retryTemplate.approvalItems))if(!retrySubjects.includes(key)){
   await retryAction(item.approverType==='subject_faculty'?'subject_faculty':key,id,{action:'stage1',approvalId:key,decision:'approved'});
 }
 const teacherUI=await browserLogin('retryTeacher');await teacherUI.page.goto('http://127.0.0.1:5051/approver-dashboard.html#requests');
 const rowFor=key=>teacherUI.page.locator(`[data-path="noDueRequests/${id}/approvals/${key}"]`);
 const [approvedKey,rejectedKey]=retrySubjects,reason='Assignment pending. Please submit before clearance.';
 const approvedResponse=teacherUI.page.waitForResponse(r=>r.url().endsWith(`/api/requests/${id}/actions`)&&r.request().postDataJSON()?.approvalId===approvedKey);await rowFor(approvedKey).getByRole('button',{name:'Approve',exact:true}).click();assert.equal((await approvedResponse).status(),200);
 await rowFor(rejectedKey).locator('.reject-btn').click();await rowFor(rejectedKey).locator('textarea').fill(reason);const rejectedResponse=teacherUI.page.waitForResponse(r=>r.url().endsWith(`/api/requests/${id}/actions`)&&r.request().postDataJSON()?.approvalId===rejectedKey);await rowFor(rejectedKey).getByRole('button',{name:'Confirm Reject',exact:true}).click();assert.equal((await rejectedResponse).status(),200);
 await teacherUI.page.waitForFunction(async id=>{const {post}=await import('/js/api.js');return (await post('/api/data/read',{path:'noDueRequests/'+id})).data?.status==='rejected';},id);
 const before=await retryRecords(id),approved=before.find(record=>record._id.endsWith('/'+approvedKey)),rejected=before.find(record=>record._id.endsWith('/'+rejectedKey));
 assert.equal(approved.status,'approved');assert.equal(rejected.remarks,reason);
 const studentUI=await browserLogin('retryStudent');await studentUI.page.goto('http://127.0.0.1:5051/student-dashboard.html#requests');await studentUI.page.getByText(reason,{exact:false}).first().waitFor();
 await studentUI.page.locator('#resubmitBtn').click();await studentUI.page.locator('#resubmitBtn').waitFor({state:'detached'});
 const after=await retryRecords(id);assert.equal(after.length,before.length);assert.deepEqual(after.find(record=>record._id===approved._id),approved);
 for(const old of before.filter(record=>record.status==='approved'))assert.deepEqual(after.find(record=>record._id===old._id),old);
 const reopened=after.find(record=>record._id===rejected._id);assert.equal(reopened.status,'pending');assert.equal(reopened.remarks,'');assert.equal(reopened.history[0].remarks,reason);assert.deepEqual(reopened.history[0].actedAt,rejected.actedAt);assert.equal(reopened.history[0].actorId,teacher.uid);
 const r=(await store.doc('noDueRequests/'+id).get()).data();assert.equal(r.approvalStates[approvedKey],'approved');assert.equal(r.approvalStates[rejectedKey],'pending');assert.equal(r.remaining,1);
 await studentUI.page.getByRole('link',{name:'Requests',exact:false}).click();await studentUI.page.getByRole('heading',{name:'My Requests',exact:true}).waitFor();
 const subjectStatuses=await studentUI.page.locator('.row').allTextContents();assert.ok(subjectStatuses.some(text=>text.includes('Software Quality Engineering')&&text.includes('approved')));assert.ok(subjectStatuses.some(text=>text.includes('Software Engineering & Project Management')&&text.includes('pending')));
 await rowFor(rejectedKey).waitFor();assert.equal(await rowFor(approvedKey).count(),0);assert.equal(await teacherUI.page.locator(`[data-path^="noDueRequests/${id}/approvals/"]`).count(),1);
 assert.match(await rowFor(rejectedKey).innerText(),/Software Engineering & Project Management/);
 const notices=await database.collection('notifications').find({requestId:id,type:'approval_resubmitted'}).toArray();assert.equal(notices.length,1);assert.equal(notices[0].__parent,teacher.uid);assert.equal(notices[0].approvalId,rejectedKey);
 const stateBeforeRepeat=await database.collection('noDueRequests').findOne({_id:id}),notificationCount=await database.collection('notifications').countDocuments({requestId:id});
 await Promise.all([1,2].map(()=>retryAction('retryStudent',id,{action:'resubmit'})));assert.deepEqual(await database.collection('noDueRequests').findOne({_id:id}),stateBeforeRepeat);assert.equal(await database.collection('notifications').countDocuments({requestId:id}),notificationCount);
 await mkdir('test/browser-artifacts',{recursive:true});await teacherUI.page.screenshot({path:'test/browser-artifacts/targeted-resubmission-teacher.png'});await studentUI.page.screenshot({path:'test/browser-artifacts/targeted-resubmission-student.png'});
 const finalApproval=teacherUI.page.waitForResponse(response=>response.url().endsWith(`/api/requests/${id}/actions`)&&response.request().postDataJSON()?.action==='stage1');
 await rowFor(rejectedKey).getByRole('button',{name:'Approve',exact:true}).click();assert.equal((await finalApproval).status(),200);await teacherUI.page.waitForFunction(async id=>{const {post}=await import('/js/api.js');return (await post('/api/data/read',{path:'noDueRequests/'+id})).data?.status==='pending_mentor';},id);
 for(const stage of ['mentor','hod'])await retryAction(stage,id,{action:stage,decision:'approved'});await retryAction('office',id,{action:'issue'});
