 await store.doc('offerings/'+offering).update({active:false});assert.equal((await api('retryStudent',retryPath(id),{action:'resubmit'})).status,400);assert.deepEqual(await retryRecords(id),before);assert.equal((await store.doc('noDueRequests/'+id).get()).data().version,7);assert.equal(await database.collection('notifications').countDocuments({requestId:id}),0);
 await store.doc('offerings/'+offering).update({active:true});await retryAction('retryStudent',id,{action:'resubmit',version:7});await retryAction('retryTeacher',id,{action:'stage1',approvalId:key,decision:'rejected',reason:'Still pending'});
 const later=await database.collection('noDueRequests').findOne({_id:id});await retryAction('retryStudent',id,{action:'resubmit',version:7});assert.deepEqual(await database.collection('noDueRequests').findOne({_id:id}),later);
 await retryAction('retryStudent',id,{action:'resubmit',version:later.version});assert.equal((await retryRecords(id)).find(row=>row._id.endsWith('/'+key)).history.length,2);
