 ({app,store}=createApp({database,client,auth,demo:true,origins:['http://127.0.0.1:5051']}));http=app.listen(3001);
 const {id,r}=await parallelFixture('exact-140'),[rejectedKey,siblingKey]=retrySubjects,reason='Assignment pending.';
 for(const [key,item]of Object.entries(r.approvalItems))if(!retrySubjects.includes(key)&&key!=='library')await retryAction(item.approverType==='subject_faculty'?'subject_faculty':key,id,{action:'stage1',approvalId:key,decision:'approved'});
 let teacher=await browserLogin('retryTeacher');await teacher.page.goto('http://127.0.0.1:5051/approver-dashboard.html#requests');
 const teacherRow=key=>teacher.page.locator(`[data-path="noDueRequests/${id}/approvals/${key}"]`);
 await teacherRow(rejectedKey).waitFor();await teacherRow(siblingKey).waitFor();assert.equal(await teacher.page.locator(`[data-path^="noDueRequests/${id}/approvals/"]`).count(),2);
 const library=await browserLogin('library');await library.page.goto('http://127.0.0.1:5051/approver-dashboard.html#requests');const libraryRow=library.page.locator(`[data-path="noDueRequests/${id}/approvals/library"]`);await libraryRow.waitFor();
 const before=await retryRecords(id),noticesBefore=await database.collection('notifications').find({requestId:id}).sort({_id:1}).toArray();
 await teacherRow(rejectedKey).locator('.reject-btn').click();await teacherRow(rejectedKey).locator('textarea').fill(reason);await teacherRow(rejectedKey).getByRole('button',{name:'Confirm Reject',exact:true}).click();
 await teacher.page.waitForFunction(async id=>{const {post}=await import('/js/api.js');return (await post('/api/data/read',{path:'noDueRequests/'+id})).data?.status==='rejected';},id);
 // Cross the real 3-second API poll, which previously removed every sibling row.
 await teacher.page.waitForTimeout(5500);
 assert.equal(await teacherRow(rejectedKey).count(),0);assert.equal(await teacherRow(siblingKey).count(),1);assert.equal(await libraryRow.count(),1);
 let saved=(await store.doc('noDueRequests/'+id).get()).data();assert.equal(saved.approvalStates[rejectedKey],'rejected');assert.equal(saved.approvalStates[siblingKey],'pending');assert.equal(saved.approvalStates.library,'pending');assert.equal(saved.approvalStates.accounts,'approved');
 const afterRejection=await retryRecords(id);for(const old of before.filter(row=>!row._id.endsWith('/'+rejectedKey)))assert.deepEqual(afterRejection.find(row=>row._id===old._id),old);
 assert.equal(afterRejection.find(row=>row._id.endsWith('/'+rejectedKey)).remarks,reason);
 for(const old of noticesBefore)assert.deepEqual(await database.collection('notifications').findOne({_id:old._id}),old);
 assert.equal(await database.collection('notifications').countDocuments({requestId:id}),noticesBefore.length+1);
 await mkdir('test/browser-artifacts',{recursive:true});await teacher.page.screenshot({path:'test/browser-artifacts/parallel-sibling-after-rejection.png'});await library.page.screenshot({path:'test/browser-artifacts/parallel-library-after-rejection.png'});
 await teacherRow(siblingKey).getByRole('button',{name:'Approve',exact:true}).click();await libraryRow.getByRole('button',{name:'Approve',exact:true}).click();
 await teacher.page.waitForFunction(async ({id,key})=>{const {post}=await import('/js/api.js'),r=(await post('/api/data/read',{path:'noDueRequests/'+id})).data;return r?.approvalStates[key]==='approved'&&r.approvalStates.library==='approved';},{id,key:siblingKey});
 saved=(await store.doc('noDueRequests/'+id).get()).data();assert.equal(saved.status,'rejected');assert.equal(saved.remaining,1);assert.equal(saved.approvalStates[rejectedKey],'rejected');assert.equal(saved.lastRejection.reason,reason);assert.equal(saved.lastRejection.approvalId,rejectedKey);
 const approvedRecords=await retryRecords(id);assert.equal(approvedRecords.find(row=>row._id.endsWith('/'+rejectedKey)).remarks,reason);
 const siblingNotice=await database.collection('notifications').findOne({requestId:id,approvalId:siblingKey});assert.equal(siblingNotice.decision,'approved');assert.equal(siblingNotice.reason,'');assert.equal(siblingNotice.status,'rejected');
 const student=await browserLogin('retryStudent');await student.page.goto('http://127.0.0.1:5051/student-dashboard.html#requests');await student.page.getByText(reason,{exact:false}).first().waitFor();
 const studentStatuses=await student.page.locator('.row').allTextContents();assert.ok(studentStatuses.some(text=>text.includes('Software Quality Engineering')&&text.includes('rejected')));assert.ok(studentStatuses.some(text=>text.includes('Software Engineering & Project Management')&&text.includes('approved')));
 await student.page.screenshot({path:'test/browser-artifacts/parallel-student-before-retry.png'});
 await student.page.locator('#resubmitBtn').click();await student.page.locator('#resubmitBtn').waitFor({state:'detached'});
 const retried=await retryRecords(id);assert.equal(retried.length,before.length);for(const old of approvedRecords.filter(row=>row.status==='approved'))assert.deepEqual(retried.find(row=>row._id===old._id),old);
 assert.equal(retried.find(row=>row._id.endsWith('/'+rejectedKey)).history[0].remarks,reason);assert.equal((await store.doc('noDueRequests/'+id).get()).data().lastRejection,null);
 assert.deepEqual(await database.collection('notifications').findOne({_id:siblingNotice._id}),siblingNotice);
 const retryNotices=await database.collection('notifications').find({requestId:id,type:'approval_resubmitted'}).toArray();assert.equal(retryNotices.length,1);assert.equal(retryNotices[0].approvalId,rejectedKey);
