test('legacy duplicate enrollment repair preserves complementary marks and historical IDs, and refuses conflicts atomically',async()=>{
 const {repairEnrollmentDuplicates}=await import('../src/services/enrollment-integrity.js');
 const {initializeModels}=await import('../src/models/index.js');
 const original=await database.collection('enrollments').findOne({studentId:students[1].uid,offeringId:offers[1].id,active:true}),prior=await database.collection('marks').findOne({_id:original._id});
 await database.collection('enrollments').dropIndex('unique_active_student_offering');
 try{
  const legacyId='integrity-legacy-enrollment',legacyMark={_id:legacyId,studentId:original.studentId,offeringId:original.offeringId,scores:{legacyExtra:9},updatedAt:new Date('2025-01-01')};
  await database.collection('enrollments').insertOne({...original,_id:legacyId});await database.collection('marks').insertOne(legacyMark);
  const historical={_id:'integrity-historical-approval',studentId:original.studentId,requestId:'integrity-historical-request',enrollmentId:legacyId,status:'approved'};await database.collection('approvals').insertOne(historical);
  const exportBefore=await marksCall('teacher2',offers[1].id,'export'),row=parseCSV(exportBefore.body.csv,[]).find(r=>r.usn===students[1].row.usn);row.IA1='20';const ambiguous=await marksCall('teacher2',offers[1].id,'preview',{csv:csvOf([row])});assert.match(ambiguous.body.rows[0].error,/data-integrity error/);
  const dry=await repairEnrollmentDuplicates(database,client);assert.equal(dry.duplicateGroups,1);assert.equal(await database.collection('enrollments').countDocuments({studentId:original.studentId,offeringId:original.offeringId,active:true}),2);
  const fixed=await repairEnrollmentDuplicates(database,client,{apply:true});assert.equal(fixed.plans[0].canonicalId,original._id);assert.equal(await database.collection('enrollments').countDocuments({studentId:original.studentId,offeringId:original.offeringId,active:true}),1);
  assert.deepEqual((await database.collection('marks').findOne({_id:original._id})).scores,{...prior.scores,legacyExtra:9});assert.deepEqual(await database.collection('marks').findOne({_id:legacyId}),legacyMark);assert.equal((await database.collection('enrollments').findOne({_id:legacyId})).duplicateOf,original._id);assert.deepEqual(await database.collection('approvals').findOne({_id:historical._id}),historical);assert.ok(await database.collection('enrollments').findOne({_id:historical.enrollmentId}));
  assert.equal((await marksCall('teacher2',offers[1].id,'preview',{csv:csvOf([row])})).body.valid,1);assert.equal((await repairEnrollmentDuplicates(database,client,{apply:true})).duplicateGroups,0);
  // A conflicting legacy score must never silently overwrite the canonical mark.
  await database.collection('enrollments').insertOne({...original,_id:'integrity-conflict'});await database.collection('marks').insertOne({_id:'integrity-conflict',studentId:original.studentId,offeringId:original.offeringId,scores:{ia1:999}});
  const before=await database.collection('marks').findOne({_id:original._id});await assert.rejects(repairEnrollmentDuplicates(database,client,{apply:true}),error=>error.conflicts.length===1);assert.deepEqual(await database.collection('marks').findOne({_id:original._id}),before);assert.equal((await database.collection('enrollments').findOne({_id:'integrity-conflict'})).active,true);
  // Fixture cleanup occurs in the isolated audit database only.
  await database.collection('enrollments').deleteOne({_id:'integrity-conflict'});await database.collection('marks').deleteOne({_id:'integrity-conflict'});
 }finally{await initializeModels(database);}
});

