test('Deterministic display-name migration changes only names and derived search copies, preserving identifiers and history',async()=>{
 const row={...students[0].row,name:'Synthetic ISE Student 47',usn:'NAMEAUDIT47',collegeEmail:'name-audit-47@demo.test'},result=await admin({action:'provision',row,requestId:'synthetic-name-audit47'});
 await store.doc('noDueRequests/name-audit-copy').set({studentId:result.uid,studentName:row.name,usn:row.usn,status:'issued',version:7});await store.doc('users/'+result.uid+'/notifications/name-copy').set({studentId:result.uid,studentName:row.name,requestId:'name-audit-copy',reason:'Preserve history',createdAt:new Date()});
 const before={};for(const c of await database.listCollections().toArray())before[c.name]=await database.collection(c.name).find({}).toArray();const plan=planDisplayNames(before);assert.deepEqual(planDisplayNames(before),plan);const conflicting=structuredClone(before);conflicting.users.find(u=>u._id===result.uid).name='Existing Real Name';assert.throws(()=>planDisplayNames(conflicting),/conflicts with a normal name/);
 const dry=await migrateDisplayNames(database,client);assert.ok(dry.identities.some(i=>i.uid===result.uid));assert.equal((await database.collection('students').findOne({_id:result.uid})).name,row.name);
 const applied=await migrateDisplayNames(database,client,{apply:true});assert.ok(applied.identities.length);assert.equal((await migrateDisplayNames(database,client,{apply:true})).changes.length,0);
 for(const [collection,rows]of Object.entries(before)){assert.equal(await database.collection(collection).countDocuments(),rows.length);for(const old of rows){const expected=structuredClone(old),change=applied.changes.find(c=>c.collection===collection&&c.id===old._id);for(const [field,value]of Object.entries(change?.fields||{})){let target=expected;const parts=field.split('.');for(const part of parts.slice(0,-1))target=target[part];target[parts.at(-1)]=value;}assert.deepEqual(await database.collection(collection).findOne({_id:old._id}),expected);}}
 assert.equal(await database.collection('students').countDocuments({name:/^Synthetic ISE Student/}),0);const renamed=await database.collection('students').findOne({_id:result.uid});const search=await api('office','/api/office/search',{term:renamed.name});assert.ok(search.body.rows.some(r=>r.uid===result.uid));
});

