test('parallel section workers reuse only the exact scoped canonical subject created between reads',async()=>{
 const {subjectRow,subjectId}=await import('../src/services/college-import.js'),row={department:'RACE',scheme:'2022',semester:2,subjectCode:'RACE501',subjectName:'Parallel section audit',credits:4};
 const dep={_id:'race-department',code:'RACE',status:'active',creationDigest:'isolated'},subject={_id:subjectId(row),departmentId:dep._id,department:row.department,scheme:row.scheme,code:row.subjectCode,name:row.subjectName,credits:4};let concurrent=subject;
 const database={collection:name=>name==='departments'?{findOne:async()=>dep}:name==='schemes'?{findOne:async()=>({code:'2022',status:'active',scope:'institution'})}:{find:()=>({toArray:async()=>[]}),findOne:async()=>concurrent}};
 assert.equal((await subjectRow(database,row)).id,subject._id);
 for(const change of [{departmentId:'another-department'},{departmentId:undefined},{scheme:'2025'},{code:'OTHER'},{name:'Conflicting name'},{semester:7}]){concurrent={...subject,...change};await assert.rejects(subjectRow(database,row),/legacy\/unscoped/);}
 concurrent=null;assert.equal((await subjectRow(database,row)).id,subject._id);
});
